PTX_SOURCE = r'''
.version 7.1
.target sm_80
.address_size 64

.visible .entry cumprod_kernel(
    .param .u64 input_ptr,
    .param .u64 output_ptr,
    .param .u32 length,
    .param .u32 batch
)
{
    // -------------------------------------------------
    // Thread identifiers
    // -------------------------------------------------
    .reg .u32 %tid;
    .reg .u32 %blockDim;
    .reg .u32 %blockIdx;
    .reg .u32 %threadIdx;

    mov.u32 %blockIdx,  %ctaid.x;
    mov.u32 %threadIdx, %tid.x;
    mov.u32 %blockDim, %ntid.x;
    mad.lo.u32 %tid, %blockIdx, %blockDim, %threadIdx;

    // -------------------------------------------------
    // Load kernel parameters
    // -------------------------------------------------
    .reg .u64 %in_base, %out_base;
    .reg .u32 %N, %B;
    ld.param.u64 %in_base,  [input_ptr];
    ld.param.u64 %out_base, [output_ptr];
    ld.param.u32 %N,       [length];
    ld.param.u32 %B,       [batch];

    // -------------------------------------------------
    // Guard: if thread id >= batch, exit
    // -------------------------------------------------
    .reg .pred %p_exit;
    setp.ge.u32 %p_exit, %tid, %B;
    @%p_exit ret;

    // -------------------------------------------------
    // Compute per‑row byte offset: offset = tid * N * sizeof(fp16)
    // -------------------------------------------------
    .reg .u64 %row_offset;
    cvt.u64.u32 %row_offset, %tid;                // tid as 64‑bit
    mul.wide.u32 %row_offset, %row_offset, %N;   // elements per row
    mul.lo.u64 %row_offset, %row_offset, 2;      // 2 bytes per fp16

    // Pointers to the start of this row
    .reg .u64 %in_ptr, %out_ptr;
    add.u64 %in_ptr,  %in_base,  %row_offset;
    add.u64 %out_ptr, %out_base, %row_offset;

    // -------------------------------------------------
    // Loop over columns
    // -------------------------------------------------
    .reg .u32  %i;
    .reg .u64  %in_addr, %out_addr;
    .reg .f16  %val16, %out16;
    .reg .f32  %val32, %acc;
    .reg .pred %p0, %p_end;

    mov.u32 %i, 0;
    mov.u64 %in_addr,  %in_ptr;
    mov.u64 %out_addr, %out_ptr;

loop_start:
    setp.ge.u32 %p_end, %i, %N;
    @%p_end bra.end;

    // Load fp16 element
    ld.global.f16 %val16, [%in_addr];
    // Convert to fp32 for accumulation
    cvt.f32.f16 %val32, %val16;

    // acc = (i==0) ? val32 : acc * val32
    setp.eq.u32 %p0, %i, 0;
    @%p0 mov.f32 %acc, %val32;
    @!%p0 mul.f32 %acc, %acc, %val32;

    // Convert back to fp16 (round‑to‑nearest) and store
    cvt.rn.f16.f32 %out16, %acc;
    st.global.f16 [%out_addr], %out16;

    // Increment addresses and loop counter
    add.u64 %in_addr,  %in_addr, 2;
    add.u64 %out_addr, %out_addr, 2;
    add.u32 %i, %i, 1;
    bra.uni loop_start;

bra.end:
    ret;
}
'''

