# -------------------------------------------------
class ModelNew:
    """
    Drop‑in replacement for the reference Model.
    Performs cumulative product along dimension 1 (columns) on fp16 tensors.
    """
    def __init__(self, dim):
        # The reference always uses dim=1; we keep the argument for API compatibility
        self.dim = dim
        # Load PTX module via the provided harness
        self.module = ptx_load(PTX_SOURCE)
        self.kernel_name = "cumprod_kernel"

        # Kernel launch configuration (one thread per row)
        self.block_size = 256
        # batch size is inferred at call time; we compute grid dynamically
        # (grid will be set in __call__)

    def __call__(self, x):
        """
        x : torch.Tensor of dtype torch.float16, shape (batch, length)
        Returns a tensor of the same shape and dtype containing the cumulative product
        along dimension 1.
        """
        assert x.dtype == torch.float16, "Input must be fp16"
        batch, length = x.shape
        out = torch.empty_like(x)

        # Compute grid size (one thread per row)
        grid_size = (batch + self.block_size - 1) // self.block_size

        # Prepare kernel arguments: input ptr, output ptr, length, batch
        args = [
            x.data_ptr(),
            out.data_ptr(),
            length,   # N
            batch     # batch count
        ]

        # Launch kernel via harness
        ptx_launch(
            self.module,
            self.kernel_name,
            (grid_size,),          # grid dimensions
            (self.block_size,),    # block dimensions
            args
        )
